#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int cols = 0, i = 0, j = 0, rows = 0;
    // 参数仅是行列数；第一行和第一列都恰好只有一种走法。
    rows = read();
    cols = read();
    for (j = 0; j < cols; j += 1)  {
        a[j] = 1;
    }
    for (i = 1; i < rows; i += 1)  {
        for (j = 1; j < cols; j += 1)  {
            // 更新前 a[j] 是上方，已经更新的 a[j-1] 是左方，所以必须从左向右。
            a[j] = (a[j] + a[(j - 1)]);
        }
    }
    // 最后一行的最后一项是右下角路径总数。
    emit(a[(cols - 1)]);
    return 0;
}

